select '86824fb9-4656-5976-949c-afe2f8f31198', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Teenagers and sleep","text":"Scientists have found that teenagers need between eight and ten hours of sleep a night. (1) ______, most of them sleep much less. One reason is biological: during adolescence, the body produces the sleep hormone later in the evening, so teenagers find it hard to fall (2) ______ before eleven. Another reason is the use of phones and computers, (3) ______ light tells the brain it is still daytime. Lack of sleep can (4) ______ concentration, mood and even school results. For this reason, some schools have decided to start classes later. (5) ______ to a study in the United States, students at these schools arrived on time more often and got better grades. Experts also (6) ______ turning off screens an hour before bed.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (2).', '[{"label":"A","text":"sleeping","is_correct":false,"distractor_type":"Usa -ing tras «fall».","explanation_feedback":"Incorrecta. No se dice «fall sleeping»."},{"label":"B","text":"slept","is_correct":false,"distractor_type":"Usa el participio.","explanation_feedback":"Incorrecta. «Fall slept» no es correcto."},{"label":"C","text":"asleep","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La expresión es «fall asleep» (quedarse dormido)."},{"label":"D","text":"sleepy","is_correct":false,"distractor_type":"Confunde «dormido» con «soñoliento».","explanation_feedback":"Incorrecta. «Fall sleepy» no existe; «sleepy» va con «feel» o «be»."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
on conflict (id) do nothing;
