select '39b5a8e8-5a1c-554f-bb04-a66b1e7621ab', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Teenagers and sleep","text":"Scientists have found that teenagers need between eight and ten hours of sleep a night. (1) ______, most of them sleep much less. One reason is biological: during adolescence, the body produces the sleep hormone later in the evening, so teenagers find it hard to fall (2) ______ before eleven. Another reason is the use of phones and computers, (3) ______ light tells the brain it is still daytime. Lack of sleep can (4) ______ concentration, mood and even school results. For this reason, some schools have decided to start classes later. (5) ______ to a study in the United States, students at these schools arrived on time more often and got better grades. Experts also (6) ______ turning off screens an hour before bed.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (3).', '[{"label":"A","text":"that","is_correct":false,"distractor_type":"Usa «that» tras una coma.","explanation_feedback":"Incorrecta. «That» no se usa después de coma en oraciones explicativas, y no indica posesión."},{"label":"B","text":"which","is_correct":false,"distractor_type":"Usa «which» sin indicar posesión.","explanation_feedback":"Incorrecta. «Which light» no conecta bien con «phones and computers»."},{"label":"C","text":"who","is_correct":false,"distractor_type":"Usa «who» para cosas.","explanation_feedback":"Incorrecta. «Who» se usa con personas."},{"label":"D","text":"whose","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Whose» indica posesión: la luz de los teléfonos y computadores."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
