select 'ec0d1441-741d-58cb-8dee-e431c74670f5', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Teenagers and sleep","text":"Scientists have found that teenagers need between eight and ten hours of sleep a night. (1) ______, most of them sleep much less. One reason is biological: during adolescence, the body produces the sleep hormone later in the evening, so teenagers find it hard to fall (2) ______ before eleven. Another reason is the use of phones and computers, (3) ______ light tells the brain it is still daytime. Lack of sleep can (4) ______ concentration, mood and even school results. For this reason, some schools have decided to start classes later. (5) ______ to a study in the United States, students at these schools arrived on time more often and got better grades. Experts also (6) ______ turning off screens an hour before bed.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"help","is_correct":false,"distractor_type":"Elige un verbo que contradice el sentido.","explanation_feedback":"Incorrecta. La falta de sueño no ayuda a la concentración."},{"label":"B","text":"affect","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Affect» (verbo) significa afectar."},{"label":"C","text":"effect","is_correct":false,"distractor_type":"Confunde el sustantivo «effect» con el verbo «affect».","explanation_feedback":"Incorrecta. Después de «can» va un verbo: «affect»."},{"label":"D","text":"increase","is_correct":false,"distractor_type":"Elige un verbo que contradice el sentido.","explanation_feedback":"Incorrecta. Dormir poco no aumenta la concentración ni mejora el ánimo."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
