select '372d3a59-e60c-5cf5-a357-e3e8dadb9109', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Teenagers and sleep","text":"Scientists have found that teenagers need between eight and ten hours of sleep a night. (1) ______, most of them sleep much less. One reason is biological: during adolescence, the body produces the sleep hormone later in the evening, so teenagers find it hard to fall (2) ______ before eleven. Another reason is the use of phones and computers, (3) ______ light tells the brain it is still daytime. Lack of sleep can (4) ______ concentration, mood and even school results. For this reason, some schools have decided to start classes later. (5) ______ to a study in the United States, students at these schools arrived on time more often and got better grades. Experts also (6) ______ turning off screens an hour before bed.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (5).', '[{"label":"A","text":"According","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «According to a study» significa «según un estudio»."},{"label":"B","text":"Thanks","is_correct":false,"distractor_type":"Atribuye los resultados al estudio.","explanation_feedback":"Incorrecta. El estudio no causó la mejora; solo la reportó."},{"label":"C","text":"Owing","is_correct":false,"distractor_type":"Usa «owing to», que indica causa.","explanation_feedback":"Incorrecta. «Owing to» expresa causa, no fuente de información."},{"label":"D","text":"Due","is_correct":false,"distractor_type":"Usa «due to», que indica causa.","explanation_feedback":"Incorrecta. «Due to a study» diría que el estudio causó la mejora."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
