insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '1e7bb647-a8f0-5030-a1a6-869cd05b72fa', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Teenagers and sleep","text":"Scientists have found that teenagers need between eight and ten hours of sleep a night. (1) ______, most of them sleep much less. One reason is biological: during adolescence, the body produces the sleep hormone later in the evening, so teenagers find it hard to fall (2) ______ before eleven. Another reason is the use of phones and computers, (3) ______ light tells the brain it is still daytime. Lack of sleep can (4) ______ concentration, mood and even school results. For this reason, some schools have decided to start classes later. (5) ______ to a study in the United States, students at these schools arrived on time more often and got better grades. Experts also (6) ______ turning off screens an hour before bed.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (6).', '[{"label":"A","text":"recommend","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Recommend + verbo -ing»: «recommend turning off»."},{"label":"B","text":"advise to","is_correct":false,"distractor_type":"Agrega «to» antes de -ing.","explanation_feedback":"Incorrecta. Se dice «advise turning off», sin «to»."},{"label":"C","text":"suggest to","is_correct":false,"distractor_type":"Agrega «to» antes de -ing.","explanation_feedback":"Incorrecta. Se dice «suggest turning off», sin «to»."},{"label":"D","text":"tell","is_correct":false,"distractor_type":"Usa «tell» sin objeto de persona.","explanation_feedback":"Incorrecta. «Tell» necesita a quién se le dice (tell people to…)."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
