insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'eb892214-32d1-5204-afe3-9e475528b1a8', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Think before you click","text":"False information spreads faster online than true information, (1) ______ to a large study of social media. The researchers believe this happens because false stories are often more surprising, and people enjoy sharing things that seem new. (2) ______ checking whether a story is true, many users share it within seconds of reading the headline. To (3) ______ this problem, some schools now teach students how to evaluate sources. They learn to ask who wrote the article, what evidence it (4) ______, and whether other reliable sources report the same thing. It sounds simple, but it requires patience. As one teacher explains, \"The goal is not to make students (5) ______ everything, but to help them think before they click.\" In a world full of information, this skill may be (6) ______ important as reading and writing.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (1).', '[{"label":"A","text":"according","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «According to a study» presenta la fuente de la información."},{"label":"B","text":"thanks","is_correct":false,"distractor_type":"Atribuye el fenómeno al estudio.","explanation_feedback":"Incorrecta. El estudio no causa que se difunda información falsa."},{"label":"C","text":"related","is_correct":false,"distractor_type":"Usa una expresión de relación general.","explanation_feedback":"Incorrecta. «Related to a study» no presenta una fuente."},{"label":"D","text":"due","is_correct":false,"distractor_type":"Usa una expresión de causa.","explanation_feedback":"Incorrecta. «Due to a study» diría que el estudio es la causa."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'b4e1e7f1-4df0-55a8-b679-8e9398bc80b1', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Think before you click","text":"False information spreads faster online than true information, (1) ______ to a large study of social media. The researchers believe this happens because false stories are often more surprising, and people enjoy sharing things that seem new. (2) ______ checking whether a story is true, many users share it within seconds of reading the headline. To (3) ______ this problem, some schools now teach students how to evaluate sources. They learn to ask who wrote the article, what evidence it (4) ______, and whether other reliable sources report the same thing. It sounds simple, but it requires patience. As one teacher explains, \"The goal is not to make students (5) ______ everything, but to help them think before they click.\" In a world full of information, this skill may be (6) ______ important as reading and writing.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (2).', '[{"label":"A","text":"As well","is_correct":false,"distractor_type":"Usa una expresión de adición incompleta.","explanation_feedback":"Incorrecta. «As well checking» no es correcto."},{"label":"B","text":"Because of","is_correct":false,"distractor_type":"Usa una expresión de causa.","explanation_feedback":"Incorrecta. No comparten la noticia por verificarla; lo hacen sin verificar."},{"label":"C","text":"In spite","is_correct":false,"distractor_type":"Omite «of» y cambia el sentido.","explanation_feedback":"Incorrecta. «In spite» necesita «of», y expresa concesión, no sustitución."},{"label":"D","text":"Instead of","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Instead of checking» significa «en lugar de verificar»."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
