select '4f609854-2566-5bea-9da5-1e20058ba2a4', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Think before you click","text":"False information spreads faster online than true information, (1) ______ to a large study of social media. The researchers believe this happens because false stories are often more surprising, and people enjoy sharing things that seem new. (2) ______ checking whether a story is true, many users share it within seconds of reading the headline. To (3) ______ this problem, some schools now teach students how to evaluate sources. They learn to ask who wrote the article, what evidence it (4) ______, and whether other reliable sources report the same thing. It sounds simple, but it requires patience. As one teacher explains, \"The goal is not to make students (5) ______ everything, but to help them think before they click.\" In a world full of information, this skill may be (6) ______ important as reading and writing.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (3).', '[{"label":"A","text":"grow","is_correct":false,"distractor_type":"Usa un verbo que cambia el sentido.","explanation_feedback":"Incorrecta. Las escuelas no quieren hacer crecer el problema."},{"label":"B","text":"happen","is_correct":false,"distractor_type":"Usa un verbo intransitivo.","explanation_feedback":"Incorrecta. «Happen this problem» no es correcto."},{"label":"C","text":"rise","is_correct":false,"distractor_type":"Usa un verbo intransitivo.","explanation_feedback":"Incorrecta. «Rise» no lleva objeto."},{"label":"D","text":"tackle","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Tackle a problem» significa enfrentar un problema."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
