select 'f9c9b3e7-ca83-5b2a-95e8-511e0dfac2a7', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Think before you click","text":"False information spreads faster online than true information, (1) ______ to a large study of social media. The researchers believe this happens because false stories are often more surprising, and people enjoy sharing things that seem new. (2) ______ checking whether a story is true, many users share it within seconds of reading the headline. To (3) ______ this problem, some schools now teach students how to evaluate sources. They learn to ask who wrote the article, what evidence it (4) ______, and whether other reliable sources report the same thing. It sounds simple, but it requires patience. As one teacher explains, \"The goal is not to make students (5) ______ everything, but to help them think before they click.\" In a world full of information, this skill may be (6) ______ important as reading and writing.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"gives up","is_correct":false,"distractor_type":"Usa un verbo frasal que significa rendirse.","explanation_feedback":"Incorrecta. «Give up» significa abandonar o rendirse."},{"label":"B","text":"makes","is_correct":false,"distractor_type":"Usa «make» con «evidence».","explanation_feedback":"Incorrecta. No se dice «make evidence» para aportar pruebas."},{"label":"C","text":"provides","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Provide evidence» significa aportar pruebas."},{"label":"D","text":"takes","is_correct":false,"distractor_type":"Usa un verbo sin la colocación adecuada.","explanation_feedback":"Incorrecta. Un artículo no «takes evidence»."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
