select '05c2b5dd-5e4e-5cb5-a72e-17c6d7a99de5', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Think before you click","text":"False information spreads faster online than true information, (1) ______ to a large study of social media. The researchers believe this happens because false stories are often more surprising, and people enjoy sharing things that seem new. (2) ______ checking whether a story is true, many users share it within seconds of reading the headline. To (3) ______ this problem, some schools now teach students how to evaluate sources. They learn to ask who wrote the article, what evidence it (4) ______, and whether other reliable sources report the same thing. It sounds simple, but it requires patience. As one teacher explains, \"The goal is not to make students (5) ______ everything, but to help them think before they click.\" In a world full of information, this skill may be (6) ______ important as reading and writing.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (6).', '[{"label":"A","text":"as","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La comparación de igualdad es «as important as»."},{"label":"B","text":"more","is_correct":false,"distractor_type":"Usa comparativo de superioridad con «as».","explanation_feedback":"Incorrecta. «More… as» mezcla dos estructuras; sería «more… than»."},{"label":"C","text":"too","is_correct":false,"distractor_type":"Usa «too» (demasiado).","explanation_feedback":"Incorrecta. «Too important as» no es correcto."},{"label":"D","text":"so","is_correct":false,"distractor_type":"Usa «so» en una comparación afirmativa.","explanation_feedback":"Incorrecta. En afirmativo se dice «as… as»."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
