select '1b1cb9e5-a1a5-54af-a99c-792cb8ec06a3', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A letter of complaint","text":"Dear Sir or Madam,\nI am writing to complain (1) ______ a pair of headphones I bought from your online shop on 3 March. When the package arrived, the box was (2) ______ and the left headphone did not work. I contacted your customer service the same day, but I have not received a (3) ______ yet. I would be grateful if you could (4) ______ the headphones or give me my money back. I have (5) ______ a photo of the damaged box to this email. I look forward to (6) ______ from you.\nYours faithfully,\nCarlos Méndez","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (1).', '[{"label":"A","text":"with","is_correct":false,"distractor_type":"Usa «with».","explanation_feedback":"Incorrecta. «Complain with» no se usa para el objeto de la queja."},{"label":"B","text":"to","is_correct":false,"distractor_type":"Confunde el objeto con la persona a quien se le reclama.","explanation_feedback":"Incorrecta. «Complain to» va con la persona (complain to the manager)."},{"label":"C","text":"about","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Se dice «complain about something» (quejarse de algo)."},{"label":"D","text":"at","is_correct":false,"distractor_type":"Usa una preposición de lugar.","explanation_feedback":"Incorrecta. «Complain at» no es correcto aquí."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
