select 'e0c6b447-198f-581e-86a8-4d7875d26e93', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A letter of complaint","text":"Dear Sir or Madam,\nI am writing to complain (1) ______ a pair of headphones I bought from your online shop on 3 March. When the package arrived, the box was (2) ______ and the left headphone did not work. I contacted your customer service the same day, but I have not received a (3) ______ yet. I would be grateful if you could (4) ______ the headphones or give me my money back. I have (5) ______ a photo of the damaged box to this email. I look forward to (6) ______ from you.\nYours faithfully,\nCarlos Méndez","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (3).', '[{"label":"A","text":"respond","is_correct":false,"distractor_type":"Usa un verbo donde va un sustantivo.","explanation_feedback":"Incorrecta. Después de «a» hace falta un sustantivo."},{"label":"B","text":"return","is_correct":false,"distractor_type":"Confunde respuesta con devolución.","explanation_feedback":"Incorrecta. «A return» es una devolución, no una respuesta."},{"label":"C","text":"reply","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Reply» es un sustantivo: «a reply» (una respuesta)."},{"label":"D","text":"answered","is_correct":false,"distractor_type":"Usa un participio donde va un sustantivo.","explanation_feedback":"Incorrecta. «A answered» no es correcto."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
