select '93c9bb2c-69d9-52ed-b3af-4b6e9717c8f6', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A letter of complaint","text":"Dear Sir or Madam,\nI am writing to complain (1) ______ a pair of headphones I bought from your online shop on 3 March. When the package arrived, the box was (2) ______ and the left headphone did not work. I contacted your customer service the same day, but I have not received a (3) ______ yet. I would be grateful if you could (4) ______ the headphones or give me my money back. I have (5) ______ a photo of the damaged box to this email. I look forward to (6) ______ from you.\nYours faithfully,\nCarlos Méndez","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"remove","is_correct":false,"distractor_type":"Confunde «reemplazar» con «quitar».","explanation_feedback":"Incorrecta. «Remove» significa retirar."},{"label":"B","text":"repeat","is_correct":false,"distractor_type":"Confunde «reemplazar» con «repetir».","explanation_feedback":"Incorrecta. No se «repiten» unos audífonos."},{"label":"C","text":"replace","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Pide que reemplacen («replace») los audífonos o que devuelvan el dinero."},{"label":"D","text":"refuse","is_correct":false,"distractor_type":"Confunde «reemplazar» con «rechazar».","explanation_feedback":"Incorrecta. Pedir que los rechacen no tiene sentido."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
