select '6d32609d-a97a-588b-8883-c5ec8e141295', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A letter of complaint","text":"Dear Sir or Madam,\nI am writing to complain (1) ______ a pair of headphones I bought from your online shop on 3 March. When the package arrived, the box was (2) ______ and the left headphone did not work. I contacted your customer service the same day, but I have not received a (3) ______ yet. I would be grateful if you could (4) ______ the headphones or give me my money back. I have (5) ______ a photo of the damaged box to this email. I look forward to (6) ______ from you.\nYours faithfully,\nCarlos Méndez","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (5).', '[{"label":"A","text":"attached","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. En un correo, los archivos se adjuntan: «attach a photo to an email»."},{"label":"B","text":"joined","is_correct":false,"distractor_type":"Traduce «unir» literalmente.","explanation_feedback":"Incorrecta. «Join» no se usa para adjuntar archivos."},{"label":"C","text":"stuck","is_correct":false,"distractor_type":"Traduce «pegar».","explanation_feedback":"Incorrecta. «Stick» es pegar físicamente."},{"label":"D","text":"tied","is_correct":false,"distractor_type":"Traduce «amarrar».","explanation_feedback":"Incorrecta. «Tie» es amarrar."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
