select 'a1f92744-8930-52be-a337-c21e5bd2d9bd', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A letter of complaint","text":"Dear Sir or Madam,\nI am writing to complain (1) ______ a pair of headphones I bought from your online shop on 3 March. When the package arrived, the box was (2) ______ and the left headphone did not work. I contacted your customer service the same day, but I have not received a (3) ______ yet. I would be grateful if you could (4) ______ the headphones or give me my money back. I have (5) ______ a photo of the damaged box to this email. I look forward to (6) ______ from you.\nYours faithfully,\nCarlos Méndez","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (6).', '[{"label":"A","text":"heard","is_correct":false,"distractor_type":"Usa el participio.","explanation_feedback":"Incorrecta. «Look forward to heard» no es correcto."},{"label":"B","text":"hearing","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. En «look forward to», «to» es preposición y va seguido de -ing."},{"label":"C","text":"be heard","is_correct":false,"distractor_type":"Usa voz pasiva.","explanation_feedback":"Incorrecta. La expresión correcta es «hearing from you»."},{"label":"D","text":"hear","is_correct":false,"distractor_type":"Trata «to» como infinitivo.","explanation_feedback":"Incorrecta. En esta expresión «to» es preposición: va «hearing»."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
