select 'b5f6fb0e-1c3c-5827-a403-1fc249f75573', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"The river of five colours","text":"Caño Cristales, in the Serranía de La Macarena, is often called \"the river of five colours\". Between July and November, a plant that grows on the rocks (1) ______ bright red, creating an amazing mix of colours together with the yellow sand, the green plants and the blue water. For many years, the area was very difficult to (2) ______ because of the armed conflict. Today, thousands of tourists visit it every year, but there are strict rules to (3) ______ the river. Visitors must go with a local guide, they are not allowed to use sun cream in the water, and the number of people per day is (4) ______. These rules may seem strict, but they exist (5) ______ the plant is very sensitive to chemicals. Thanks to them, the river has kept its colours, and the local community (6) ______ money from tourism.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (1).', '[{"label":"A","text":"gets on","is_correct":false,"distractor_type":"Usa un verbo frasal de otra función.","explanation_feedback":"Incorrecta. «Get on» significa subirse o llevarse bien."},{"label":"B","text":"makes","is_correct":false,"distractor_type":"Usa «make» sin objeto.","explanation_feedback":"Incorrecta. «The plant makes bright red» no es correcto."},{"label":"C","text":"turns","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Turn + color» significa ponerse de ese color."},{"label":"D","text":"puts","is_correct":false,"distractor_type":"Usa un verbo de colocar.","explanation_feedback":"Incorrecta. «Puts bright red» no tiene sentido."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
