select '98f32772-e19b-5261-9e48-876bb91fe712', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"The river of five colours","text":"Caño Cristales, in the Serranía de La Macarena, is often called \"the river of five colours\". Between July and November, a plant that grows on the rocks (1) ______ bright red, creating an amazing mix of colours together with the yellow sand, the green plants and the blue water. For many years, the area was very difficult to (2) ______ because of the armed conflict. Today, thousands of tourists visit it every year, but there are strict rules to (3) ______ the river. Visitors must go with a local guide, they are not allowed to use sun cream in the water, and the number of people per day is (4) ______. These rules may seem strict, but they exist (5) ______ the plant is very sensitive to chemicals. Thanks to them, the river has kept its colours, and the local community (6) ______ money from tourism.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (2).', '[{"label":"A","text":"reach","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Reach» significa llegar a un lugar y lleva objeto directo."},{"label":"B","text":"arrive","is_correct":false,"distractor_type":"Usa «arrive» sin preposición.","explanation_feedback":"Incorrecta. Se diría «arrive at» o «arrive in»."},{"label":"C","text":"achieve","is_correct":false,"distractor_type":"Confunde llegar con lograr.","explanation_feedback":"Incorrecta. «Achieve» es lograr una meta, no llegar a un lugar."},{"label":"D","text":"get","is_correct":false,"distractor_type":"Usa «get» sin «to».","explanation_feedback":"Incorrecta. Para lugares se dice «get to»."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
