select '12eb6582-b3f0-59ad-92d7-276526b85bf5', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"The river of five colours","text":"Caño Cristales, in the Serranía de La Macarena, is often called \"the river of five colours\". Between July and November, a plant that grows on the rocks (1) ______ bright red, creating an amazing mix of colours together with the yellow sand, the green plants and the blue water. For many years, the area was very difficult to (2) ______ because of the armed conflict. Today, thousands of tourists visit it every year, but there are strict rules to (3) ______ the river. Visitors must go with a local guide, they are not allowed to use sun cream in the water, and the number of people per day is (4) ______. These rules may seem strict, but they exist (5) ______ the plant is very sensitive to chemicals. Thanks to them, the river has kept its colours, and the local community (6) ______ money from tourism.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"limited","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Is limited» significa que hay un límite de visitantes por día."},{"label":"B","text":"closed","is_correct":false,"distractor_type":"Usa un adjetivo para lugares.","explanation_feedback":"Incorrecta. Un número no se «cierra»."},{"label":"C","text":"reduced to","is_correct":false,"distractor_type":"Deja la expresión incompleta.","explanation_feedback":"Incorrecta. «Reduced to» necesita un número después."},{"label":"D","text":"finished","is_correct":false,"distractor_type":"Usa un adjetivo que no tiene sentido aquí.","explanation_feedback":"Incorrecta. El número de personas no está «terminado»."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
