select '43d91108-9532-583e-996c-c0cc3593f809', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"The river of five colours","text":"Caño Cristales, in the Serranía de La Macarena, is often called \"the river of five colours\". Between July and November, a plant that grows on the rocks (1) ______ bright red, creating an amazing mix of colours together with the yellow sand, the green plants and the blue water. For many years, the area was very difficult to (2) ______ because of the armed conflict. Today, thousands of tourists visit it every year, but there are strict rules to (3) ______ the river. Visitors must go with a local guide, they are not allowed to use sun cream in the water, and the number of people per day is (4) ______. These rules may seem strict, but they exist (5) ______ the plant is very sensitive to chemicals. Thanks to them, the river has kept its colours, and the local community (6) ______ money from tourism.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (5).', '[{"label":"A","text":"unless","is_correct":false,"distractor_type":"Usa un conector de condición negativa.","explanation_feedback":"Incorrecta. «Unless» significa «a menos que»."},{"label":"B","text":"although","is_correct":false,"distractor_type":"Usa un conector de concesión.","explanation_feedback":"Incorrecta. No hay contraste entre la sensibilidad y las reglas."},{"label":"C","text":"so that","is_correct":false,"distractor_type":"Usa un conector de finalidad.","explanation_feedback":"Incorrecta. La sensibilidad de la planta no es la finalidad de las reglas."},{"label":"D","text":"because","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Las reglas existen porque la planta es muy sensible a los químicos."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
