select '9a8f63a6-a36a-58ac-8b30-21ae6bbf323b', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Never too late","text":"It is often said that children learn languages more easily than adults. (1) ______ this is partly true for pronunciation, adults actually have several advantages. They usually have better study habits, a larger vocabulary in their own language, and a clearer idea of (2) ______ they want to learn. The main difficulty for many adults is not their brain but their fear of (3) ______ mistakes in front of others. Children rarely worry about sounding silly, so they (4) ______ more risks when they speak. Teachers therefore recommend that adult learners focus on communication rather than perfection. \"Nobody (5) ______ you to speak like a native speaker,\" says one teacher. \"What matters is that people understand you.\" With regular practice, it is never too late to (6) ______ a new language.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (1).', '[{"label":"A","text":"Because","is_correct":false,"distractor_type":"Usa un conector de causa.","explanation_feedback":"Incorrecta. No hay relación causal entre las dos ideas."},{"label":"B","text":"Although","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Although» introduce una concesión: aunque sea cierto en pronunciación, los adultos tienen ventajas."},{"label":"C","text":"Despite","is_correct":false,"distractor_type":"Usa «despite» delante de una oración.","explanation_feedback":"Incorrecta. «Despite» va con sustantivo o -ing, no con «this is…»."},{"label":"D","text":"However","is_correct":false,"distractor_type":"Usa «however» para unir dos oraciones con coma.","explanation_feedback":"Incorrecta. «However» no subordina una oración a otra así."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
