select '86c780d1-aef2-5795-9593-ce3a3725fad0', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Never too late","text":"It is often said that children learn languages more easily than adults. (1) ______ this is partly true for pronunciation, adults actually have several advantages. They usually have better study habits, a larger vocabulary in their own language, and a clearer idea of (2) ______ they want to learn. The main difficulty for many adults is not their brain but their fear of (3) ______ mistakes in front of others. Children rarely worry about sounding silly, so they (4) ______ more risks when they speak. Teachers therefore recommend that adult learners focus on communication rather than perfection. \"Nobody (5) ______ you to speak like a native speaker,\" says one teacher. \"What matters is that people understand you.\" With regular practice, it is never too late to (6) ______ a new language.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (3).', '[{"label":"A","text":"making","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La colocación es «make mistakes», y tras «of» va -ing."},{"label":"B","text":"taking","is_correct":false,"distractor_type":"Usa «take» con «mistakes».","explanation_feedback":"Incorrecta. «Take mistakes» no es una colocación."},{"label":"C","text":"having","is_correct":false,"distractor_type":"Usa «have» con «mistakes».","explanation_feedback":"Incorrecta. No se dice «have mistakes» con este sentido."},{"label":"D","text":"doing","is_correct":false,"distractor_type":"Traduce «hacer» como «do».","explanation_feedback":"Incorrecta. Con «mistakes» se usa «make»."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
