select 'cc16e18d-0e26-5447-bba2-a9769d3ddcb6', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Never too late","text":"It is often said that children learn languages more easily than adults. (1) ______ this is partly true for pronunciation, adults actually have several advantages. They usually have better study habits, a larger vocabulary in their own language, and a clearer idea of (2) ______ they want to learn. The main difficulty for many adults is not their brain but their fear of (3) ______ mistakes in front of others. Children rarely worry about sounding silly, so they (4) ______ more risks when they speak. Teachers therefore recommend that adult learners focus on communication rather than perfection. \"Nobody (5) ______ you to speak like a native speaker,\" says one teacher. \"What matters is that people understand you.\" With regular practice, it is never too late to (6) ______ a new language.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"do","is_correct":false,"distractor_type":"Usa «do» con «risks».","explanation_feedback":"Incorrecta. No se dice «do risks»."},{"label":"B","text":"make","is_correct":false,"distractor_type":"Usa «make» con «risks».","explanation_feedback":"Incorrecta. No se dice «make risks»."},{"label":"C","text":"give","is_correct":false,"distractor_type":"Usa «give» con «risks».","explanation_feedback":"Incorrecta. No se dice «give risks»."},{"label":"D","text":"take","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La colocación es «take risks» (correr riesgos)."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
on conflict (id) do nothing;
