select 'd455c748-3cd5-5069-8259-ffacc8204121', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Never too late","text":"It is often said that children learn languages more easily than adults. (1) ______ this is partly true for pronunciation, adults actually have several advantages. They usually have better study habits, a larger vocabulary in their own language, and a clearer idea of (2) ______ they want to learn. The main difficulty for many adults is not their brain but their fear of (3) ______ mistakes in front of others. Children rarely worry about sounding silly, so they (4) ______ more risks when they speak. Teachers therefore recommend that adult learners focus on communication rather than perfection. \"Nobody (5) ______ you to speak like a native speaker,\" says one teacher. \"What matters is that people understand you.\" With regular practice, it is never too late to (6) ______ a new language.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (5).', '[{"label":"A","text":"expects","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Expect someone to do something» significa esperar que alguien haga algo."},{"label":"B","text":"hopes","is_correct":false,"distractor_type":"Usa «hope» con objeto + infinitivo.","explanation_feedback":"Incorrecta. No se dice «hopes you to»."},{"label":"C","text":"waits","is_correct":false,"distractor_type":"Confunde «esperar» (aguardar) con «esperar que».","explanation_feedback":"Incorrecta. «Wait» es aguardar y no lleva esta estructura."},{"label":"D","text":"looks","is_correct":false,"distractor_type":"Usa un verbo de percepción.","explanation_feedback":"Incorrecta. «Looks you to» no es correcto."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
