select '7be23218-fa69-52d8-84dd-501340e21f39', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Never too late","text":"It is often said that children learn languages more easily than adults. (1) ______ this is partly true for pronunciation, adults actually have several advantages. They usually have better study habits, a larger vocabulary in their own language, and a clearer idea of (2) ______ they want to learn. The main difficulty for many adults is not their brain but their fear of (3) ______ mistakes in front of others. Children rarely worry about sounding silly, so they (4) ______ more risks when they speak. Teachers therefore recommend that adult learners focus on communication rather than perfection. \"Nobody (5) ______ you to speak like a native speaker,\" says one teacher. \"What matters is that people understand you.\" With regular practice, it is never too late to (6) ______ a new language.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (6).', '[{"label":"A","text":"take off","is_correct":false,"distractor_type":"Usa un verbo frasal sin relación.","explanation_feedback":"Incorrecta. «Take off» es despegar o quitarse ropa."},{"label":"B","text":"give up","is_correct":false,"distractor_type":"Invierte el sentido.","explanation_feedback":"Incorrecta. «Give up» es abandonar, lo contrario del mensaje."},{"label":"C","text":"pick out","is_correct":false,"distractor_type":"Confunde verbos frasales con «pick».","explanation_feedback":"Incorrecta. «Pick out» es escoger entre varios."},{"label":"D","text":"pick up","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Pick up a language» significa aprender un idioma de manera informal."}]'::jsonb, 'B+', 1.3, 1.3, 0.25, 50, 'original_generated'
