insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'f5719932-9be1-52a5-b48c-7a8043a4a37a', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Voices of the countryside","text":"In many rural areas of Colombia, community radio stations play an important (1) ______ in people''s lives. They are run by local volunteers and broadcast news, music and programmes in local languages. For farmers, the radio is often the quickest way to find (2) ______ about the weather or the price of their products. During emergencies, such as floods, stations can warn people (3) ______ the danger. Many young people also take (4) ______ in the stations, learning to write scripts, interview guests and use recording equipment. (5) ______ the internet is growing, many listeners say they will never stop listening to their local radio, because it talks about their own (6) ______ and problems.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (1).', '[{"label":"A","text":"paper","is_correct":false,"distractor_type":"Falso amigo: «papel» no se traduce «paper» en este sentido.","explanation_feedback":"Incorrecta. «Paper» es papel físico; el papel o función es «role»."},{"label":"B","text":"game","is_correct":false,"distractor_type":"Traduce «play» como jugar.","explanation_feedback":"Incorrecta. «Play a game» es jugar un juego, no cumplir una función."},{"label":"C","text":"work","is_correct":false,"distractor_type":"Usa «work» con «play».","explanation_feedback":"Incorrecta. «Play an important work» no es correcto."},{"label":"D","text":"role","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La colocación es «play an important role» (cumplir un papel importante)."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
on conflict (id) do nothing;
