select '1e43d27c-b698-59fd-b18a-c7a6a1f29f9d', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Voices of the countryside","text":"In many rural areas of Colombia, community radio stations play an important (1) ______ in people''s lives. They are run by local volunteers and broadcast news, music and programmes in local languages. For farmers, the radio is often the quickest way to find (2) ______ about the weather or the price of their products. During emergencies, such as floods, stations can warn people (3) ______ the danger. Many young people also take (4) ______ in the stations, learning to write scripts, interview guests and use recording equipment. (5) ______ the internet is growing, many listeners say they will never stop listening to their local radio, because it talks about their own (6) ______ and problems.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (2).', '[{"label":"A","text":"up","is_correct":false,"distractor_type":"Combina «find» con «up».","explanation_feedback":"Incorrecta. «Find up» no existe."},{"label":"B","text":"out","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Find out» significa averiguar o enterarse."},{"label":"C","text":"off","is_correct":false,"distractor_type":"Combina «find» con «off».","explanation_feedback":"Incorrecta. «Find off» no existe."},{"label":"D","text":"on","is_correct":false,"distractor_type":"Combina «find» con «on».","explanation_feedback":"Incorrecta. «Find on» no significa averiguar."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
