select '69c912ce-5480-562e-beb4-5011a9a0a18d', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Voices of the countryside","text":"In many rural areas of Colombia, community radio stations play an important (1) ______ in people''s lives. They are run by local volunteers and broadcast news, music and programmes in local languages. For farmers, the radio is often the quickest way to find (2) ______ about the weather or the price of their products. During emergencies, such as floods, stations can warn people (3) ______ the danger. Many young people also take (4) ______ in the stations, learning to write scripts, interview guests and use recording equipment. (5) ______ the internet is growing, many listeners say they will never stop listening to their local radio, because it talks about their own (6) ______ and problems.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (3).', '[{"label":"A","text":"in","is_correct":false,"distractor_type":"Usa una preposición de lugar.","explanation_feedback":"Incorrecta. «Warn people in the danger» no tiene sentido."},{"label":"B","text":"for","is_correct":false,"distractor_type":"Traduce «por» o «para».","explanation_feedback":"Incorrecta. «Warn people for» no es correcto."},{"label":"C","text":"to","is_correct":false,"distractor_type":"Usa «to» sin verbo.","explanation_feedback":"Incorrecta. «Warn people to» necesitaría un verbo (to leave)."},{"label":"D","text":"about","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Se dice «warn someone about something» (advertir sobre algo)."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
