select 'c96e6051-ff20-5467-824d-84282deedb99', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Voices of the countryside","text":"In many rural areas of Colombia, community radio stations play an important (1) ______ in people''s lives. They are run by local volunteers and broadcast news, music and programmes in local languages. For farmers, the radio is often the quickest way to find (2) ______ about the weather or the price of their products. During emergencies, such as floods, stations can warn people (3) ______ the danger. Many young people also take (4) ______ in the stations, learning to write scripts, interview guests and use recording equipment. (5) ______ the internet is growing, many listeners say they will never stop listening to their local radio, because it talks about their own (6) ______ and problems.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"place","is_correct":false,"distractor_type":"Usa «take place», que significa ocurrir.","explanation_feedback":"Incorrecta. «Take place» es tener lugar; no se usa con personas."},{"label":"B","text":"care","is_correct":false,"distractor_type":"Usa «take care», que significa cuidar.","explanation_feedback":"Incorrecta. «Take care in the stations» no significa participar."},{"label":"C","text":"notice","is_correct":false,"distractor_type":"Usa «take notice», que significa prestar atención.","explanation_feedback":"Incorrecta. No expresa participación."},{"label":"D","text":"part","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Take part in» significa participar."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
