select 'dfaff05d-e155-5f18-8488-826644efdd2b', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Voices of the countryside","text":"In many rural areas of Colombia, community radio stations play an important (1) ______ in people''s lives. They are run by local volunteers and broadcast news, music and programmes in local languages. For farmers, the radio is often the quickest way to find (2) ______ about the weather or the price of their products. During emergencies, such as floods, stations can warn people (3) ______ the danger. Many young people also take (4) ______ in the stations, learning to write scripts, interview guests and use recording equipment. (5) ______ the internet is growing, many listeners say they will never stop listening to their local radio, because it talks about their own (6) ______ and problems.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (5).', '[{"label":"A","text":"Despite","is_correct":false,"distractor_type":"Usa «despite» delante de una oración.","explanation_feedback":"Incorrecta. «Despite» va con sustantivo o -ing."},{"label":"B","text":"Unless","is_correct":false,"distractor_type":"Usa una condición negativa.","explanation_feedback":"Incorrecta. «Unless» significa «a menos que» y no tiene sentido aquí."},{"label":"C","text":"Because","is_correct":false,"distractor_type":"Usa un conector de causa.","explanation_feedback":"Incorrecta. El crecimiento de internet no es la razón para seguir escuchando radio."},{"label":"D","text":"Although","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Hay concesión: aunque internet crece, siguen escuchando la radio."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
