select 'f8a81884-a2f2-541d-88ab-79a5380270fa', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"Voices of the countryside","text":"In many rural areas of Colombia, community radio stations play an important (1) ______ in people''s lives. They are run by local volunteers and broadcast news, music and programmes in local languages. For farmers, the radio is often the quickest way to find (2) ______ about the weather or the price of their products. During emergencies, such as floods, stations can warn people (3) ______ the danger. Many young people also take (4) ______ in the stations, learning to write scripts, interview guests and use recording equipment. (5) ______ the internet is growing, many listeners say they will never stop listening to their local radio, because it talks about their own (6) ______ and problems.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (6).', '[{"label":"A","text":"communicate","is_correct":false,"distractor_type":"Usa un verbo donde va un sustantivo.","explanation_feedback":"Incorrecta. Después de «their own» va un sustantivo."},{"label":"B","text":"common","is_correct":false,"distractor_type":"Usa un adjetivo sin sustantivo.","explanation_feedback":"Incorrecta. «Their own common» queda incompleto."},{"label":"C","text":"commonly","is_correct":false,"distractor_type":"Usa un adverbio.","explanation_feedback":"Incorrecta. Un adverbio no puede ir después de «their own»."},{"label":"D","text":"community","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Hace falta un sustantivo: «their own community» (su propia comunidad)."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
