select '88f79574-505a-561e-a820-45f8a5297494', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A bike for every student","text":"In some rural parts of Colombia, students walk more than an hour to reach their school. A programme in Boyacá decided to (1) ______ this by giving bicycles to students who live far away. The idea was simple, but the results were (2) ______. In the first year, the number of students who missed classes went (3) ______ by almost a third. Teachers also noticed that students arrived less tired and were more (4) ______ during lessons. Each student has to look (5) ______ their bicycle, and a local mechanic visits the schools every month to repair the ones that are broken. Other regions are now thinking (6) ______ starting similar programmes.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (1).', '[{"label":"A","text":"rise","is_correct":false,"distractor_type":"Usa un verbo intransitivo.","explanation_feedback":"Incorrecta. «Rise» no lleva objeto."},{"label":"B","text":"change","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El programa quiso cambiar («change») esa situación."},{"label":"C","text":"happen","is_correct":false,"distractor_type":"Usa un verbo intransitivo.","explanation_feedback":"Incorrecta. «Happen this» no es correcto."},{"label":"D","text":"arrive","is_correct":false,"distractor_type":"Usa un verbo intransitivo de movimiento.","explanation_feedback":"Incorrecta. «Arrive this» no es correcto."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
