select '279c6f74-b4f1-5791-a0b3-6ffa5920be64', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A bike for every student","text":"In some rural parts of Colombia, students walk more than an hour to reach their school. A programme in Boyacá decided to (1) ______ this by giving bicycles to students who live far away. The idea was simple, but the results were (2) ______. In the first year, the number of students who missed classes went (3) ______ by almost a third. Teachers also noticed that students arrived less tired and were more (4) ______ during lessons. Each student has to look (5) ______ their bicycle, and a local mechanic visits the schools every month to repair the ones that are broken. Other regions are now thinking (6) ______ starting similar programmes.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (2).', '[{"label":"A","text":"impressive","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El contraste «simple, but…» pide un adjetivo positivo: impresionantes."},{"label":"B","text":"disappointing","is_correct":false,"distractor_type":"Ignora los resultados positivos del texto.","explanation_feedback":"Incorrecta. Los resultados fueron buenos, no decepcionantes."},{"label":"C","text":"expensive","is_correct":false,"distractor_type":"Elige un adjetivo sin apoyo en el texto.","explanation_feedback":"Incorrecta. El texto no habla de costos de los resultados."},{"label":"D","text":"impressed","is_correct":false,"distractor_type":"Confunde -ed con -ing/-ive.","explanation_feedback":"Incorrecta. «Impressed» describe a quien siente la impresión, no a los resultados."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '7d7da583-0c9a-5b3a-9eea-15195e6330b9', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A bike for every student","text":"In some rural parts of Colombia, students walk more than an hour to reach their school. A programme in Boyacá decided to (1) ______ this by giving bicycles to students who live far away. The idea was simple, but the results were (2) ______. In the first year, the number of students who missed classes went (3) ______ by almost a third. Teachers also noticed that students arrived less tired and were more (4) ______ during lessons. Each student has to look (5) ______ their bicycle, and a local mechanic visits the schools every month to repair the ones that are broken. Other regions are now thinking (6) ______ starting similar programmes.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (3).', '[{"label":"A","text":"on","is_correct":false,"distractor_type":"Usa un verbo frasal de otra función.","explanation_feedback":"Incorrecta. «Go on» es continuar."},{"label":"B","text":"down","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Go down» significa disminuir: bajó la inasistencia."},{"label":"C","text":"off","is_correct":false,"distractor_type":"Usa un verbo frasal de otra función.","explanation_feedback":"Incorrecta. «Go off» es sonar (una alarma) o dañarse un alimento."},{"label":"D","text":"up","is_correct":false,"distractor_type":"Invierte el sentido.","explanation_feedback":"Incorrecta. «Go up» es aumentar, y la inasistencia bajó."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
