select '6341c79e-8ebf-5459-adb1-d258bc0c85ab', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A bike for every student","text":"In some rural parts of Colombia, students walk more than an hour to reach their school. A programme in Boyacá decided to (1) ______ this by giving bicycles to students who live far away. The idea was simple, but the results were (2) ______. In the first year, the number of students who missed classes went (3) ______ by almost a third. Teachers also noticed that students arrived less tired and were more (4) ______ during lessons. Each student has to look (5) ______ their bicycle, and a local mechanic visits the schools every month to repair the ones that are broken. Other regions are now thinking (6) ______ starting similar programmes.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (4).', '[{"label":"A","text":"bored","is_correct":false,"distractor_type":"Contradice la mejora descrita.","explanation_feedback":"Incorrecta. Llegar menos cansados no hace que se aburran más."},{"label":"B","text":"focused","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Focused» significa concentrado, lo que se espera si llegan menos cansados."},{"label":"C","text":"absent","is_correct":false,"distractor_type":"Contradice que están en clase.","explanation_feedback":"Incorrecta. No se puede estar ausente «during lessons»."},{"label":"D","text":"sleepy","is_correct":false,"distractor_type":"Contradice «less tired».","explanation_feedback":"Incorrecta. Si llegan menos cansados, no estarían más soñolientos."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
