select '2a52113a-fe19-544a-ac87-f5e8edc25d40', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A bike for every student","text":"In some rural parts of Colombia, students walk more than an hour to reach their school. A programme in Boyacá decided to (1) ______ this by giving bicycles to students who live far away. The idea was simple, but the results were (2) ______. In the first year, the number of students who missed classes went (3) ______ by almost a third. Teachers also noticed that students arrived less tired and were more (4) ______ during lessons. Each student has to look (5) ______ their bicycle, and a local mechanic visits the schools every month to repair the ones that are broken. Other regions are now thinking (6) ______ starting similar programmes.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (5).', '[{"label":"A","text":"at","is_correct":false,"distractor_type":"Usa «look at», que significa mirar.","explanation_feedback":"Incorrecta. Mirar la bicicleta no es cuidarla."},{"label":"B","text":"for","is_correct":false,"distractor_type":"Usa «look for», que significa buscar.","explanation_feedback":"Incorrecta. Buscar la bicicleta no es la responsabilidad descrita."},{"label":"C","text":"after","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. «Look after» significa cuidar."},{"label":"D","text":"up","is_correct":false,"distractor_type":"Usa «look up», que significa buscar información.","explanation_feedback":"Incorrecta. «Look up» se usa con datos, no con objetos que se cuidan."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
from public.evidences e where e.code = 'IN.E7'
