select '245d8aca-a560-5a5a-b544-4ec12f9f7c1e', e.id, 'IN', (select id from public.content_components where code = 'IN.P7'), 'qa_passed', 'cefr_part', '{"title":"A bike for every student","text":"In some rural parts of Colombia, students walk more than an hour to reach their school. A programme in Boyacá decided to (1) ______ this by giving bicycles to students who live far away. The idea was simple, but the results were (2) ______. In the first year, the number of students who missed classes went (3) ______ by almost a third. Teachers also noticed that students arrived less tired and were more (4) ______ during lessons. Each student has to look (5) ______ their bicycle, and a local mechanic visits the schools every month to repair the ones that are broken. Other regions are now thinking (6) ______ starting similar programmes.","svg":null,"table":null}'::jsonb, 'Choose the word or words that best fill gap (6).', '[{"label":"A","text":"about","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Se dice «think about doing something» (pensar en hacer algo)."},{"label":"B","text":"on","is_correct":false,"distractor_type":"Usa «think on».","explanation_feedback":"Incorrecta. «Think on» no es la forma habitual."},{"label":"C","text":"in","is_correct":false,"distractor_type":"Traduce «pensar en» literalmente.","explanation_feedback":"Incorrecta. En inglés no se dice «think in» con este sentido."},{"label":"D","text":"to","is_correct":false,"distractor_type":"Usa «to» tras «think».","explanation_feedback":"Incorrecta. «Think to starting» no es correcto."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 50, 'original_generated'
